ee:message.ee:set-payload:
%dw 2.0
import * from dw::core::Strings
import * from dw::Runtime
output application/java

fun asObject(source) =
    if (source == null) null
    else if (source is Object or source is Array) source
    else if (source is String) (try(() -> read(source, "application/json")) orElse null)
    else null

fun resolveField(source, field: String) =
    do {
        var obj = asObject(source)
        ---
        if (obj == null) null
        else if (obj is Object) obj[field]
        else null
    }

fun firstChar(s: String): String = substring(s, 0, 1)
fun lastChar(s: String): String = substring(s, sizeOf(s) - 1, sizeOf(s))
fun isNumericLiteral(s: String): Boolean = s matches /-?\d+(\.\d+)?/
fun stripQuotes(s: String): String =
    if (sizeOf(s) >= 2 and (
            (firstChar(s) == "'" and lastChar(s) == "'") or
            (firstChar(s) == "\"" and lastChar(s) == "\"")
        ))
        substring(s, 1, sizeOf(s) - 1)
    else s

fun resolveValue(exprRaw, b, h, uv, sc) =
    do {
        var expr = trim(exprRaw default "")
        ---
        if (expr == "") ""
        else if (isNumericLiteral(expr)) (expr as Number)
        else if (sizeOf(expr) >= 2 and (
                    (firstChar(expr) == "'" and lastChar(expr) == "'") or
                    (firstChar(expr) == "\"" and lastChar(expr) == "\"")
                ))
            stripQuotes(expr)
        // payload/attributes.headers/attributes.statusCode are Mule/DataWeave's own native names
        // for these (attributes.headers being a real MultiMap-shaped object) — the only names
        // recognized, no body/headers aliases.
        else if (expr == "payload") b
        else if (startsWith(expr, "payload.")) resolveField(b, substring(expr, 8, sizeOf(expr)))
        else if (expr == "attributes.headers") h
        else if (startsWith(expr, "attributes.headers.")) (if (h != null) h[(substring(expr, 19, sizeOf(expr)))] else null)
        else if (expr == "attributes.statusCode") sc
        else if (startsWith(expr, "vars.")) do {
            var rest = substring(expr, 5, sizeOf(expr))
            var parts = rest splitBy "."
            ---
            if (sizeOf(parts) <= 1) uv[rest] else resolveField(uv[(parts[0])], (parts[1 to -1]) joinBy ".")
        }
        else expr
    }

fun stringifyVal(v) =
    if (v == null) "null"
    else if (v is Object or v is Array) write(v, "application/json")
    else (v as String)

fun typeOfVal(v) =
    if (v == null) "undefined"
    else if (v is Boolean) "boolean"
    else if (v is Number) "number"
    else if (v is String) "string"
    else "object"

fun asNumVal(v) =
    if (v is Number) v
    else if (v is String) (try(() -> (trim(v) as Number)) orElse null)
    else null

fun compareStr(l, r, op: String): Boolean =
    do {
        var ls = stringifyVal(l)
        var rs = stringifyVal(r)
        ---
        if (op == "neq" or op == "!=") ls != rs
        else if (op == "gt" or op == ">") ls > rs
        else if (op == "gte" or op == ">=") ls >= rs
        else if (op == "lt" or op == "<") ls < rs
        else if (op == "lte" or op == "<=") ls <= rs
        else ls == rs
    }

fun compareVal(l, r, op: String): Boolean =
    do {
        var ln = asNumVal(l)
        var rn = asNumVal(r)
        ---
        if (ln != null and rn != null and op != "==" and op != "!=")
            (if (op == "gt" or op == ">") ln > rn
             else if (op == "gte" or op == ">=") ln >= rn
             else if (op == "lt" or op == "<") ln < rn
             else if (op == "lte" or op == "<=") ln <= rn
             else compareStr(l, r, op))
        else compareStr(l, r, op)
    }

var b = vars.postChainBody
var h = vars.postChainHeaders default {}
var uv = vars.rsVars default {}
// The status code from the actual HTTP call this postResponse chain is running after — captured
// into vars.rsResponse back where the response itself was captured (still in scope here via
// flow-ref's shared vars, same as postChainBody/postChainHeaders above).
var sc = vars.rsResponse.status default null
var step = payload
var stepName = if (step.name != null and trim(step.name) != "") step.name else "Assertion"
var isOr = upper(step.logic default "AND") == "OR"
var stepOnFail = step.onFail default "stop"
var stepConditions = step.conditions default []

var conditionResults = stepConditions map ((c, idx) -> do {
    var left = resolveValue(c.left default "", b, h, uv, sc)
    var op = c.operator default "=="
    var right = trim(c.right default "")
    ---
    if (op == "notNull")
        { left: (c.left default ""), operator: op, right: (c.right default ""), passed: (left != null), message: ("actual=" ++ stringifyVal(left) ++ "  expected: not null"), idx: idx }
    else if (op == "contains")
        do {
            var rv = resolveValue(right, b, h, uv, sc)
            var passed = stringifyVal(left) contains stringifyVal(rv)
            ---
            { left: (c.left default ""), operator: op, right: (c.right default ""), passed: passed, message: ("actual=\"" ++ stringifyVal(left) ++ "\"  expected to contain: \"" ++ stringifyVal(rv) ++ "\""), idx: idx }
        }
    else if (op == "typeof")
        do {
            var actualType = typeOfVal(left)
            var passed = actualType == right
            ---
            { left: (c.left default ""), operator: op, right: (c.right default ""), passed: passed, message: ("actual typeof=" ++ actualType ++ "  expected type: " ++ right), idx: idx }
        }
    else
        do {
            var rv2 = resolveValue(right, b, h, uv, sc)
            var passed = compareVal(left, rv2, op)
            ---
            { left: (c.left default ""), operator: op, right: (c.right default ""), passed: passed, message: ("actual=\"" ++ stringifyVal(left) ++ "\"  expected " ++ op ++ " \"" ++ stringifyVal(rv2) ++ "\""), idx: idx }
        }
})

var passCount = sizeOf(conditionResults filter ((r) -> r.passed))
var failures = (conditionResults filter ((r) -> !r.passed)) map ((r) -> ("Condition " ++ ((r.idx + 1) as String) ++ ": " ++ r.message))
var overallPass = sizeOf(stepConditions) == 0 or (if (isOr) passCount > 0 else sizeOf(failures) == 0)
var failMsgHeader = if (isOr) "Assertion failed (no condition passed):\n" else "Assertion failed:\n"
var baseResult = {
    name: stepName,
    "type": "assertion",
    passed: overallPass,
    logic: (if (isOr) "OR" else "AND"),
    conditions: (conditionResults map ((r) -> { left: r.left, operator: r.operator, right: r.right, passed: r.passed, message: r.message }))
}
var finalResult = if (overallPass) baseResult else (baseResult ++ { message: (failMsgHeader ++ (failures joinBy "\n")) })
---
{ result: finalResult, onFail: stepOnFail, overallPass: overallPass }

%dw 2.0
import * from dw::core::Strings
import * from dw::core::Arrays
import * from dw::Runtime
output application/java

fun asJson(v) =
    if (v == null) null
    else if (v is String) (try(() -> read(v, "application/json")) orElse v)
    else v

fun stringifyVal(v) =
    if (v == null) ""
    else if (v is Object or v is Array) write(v, "application/json")
    else (v as String)

// Deep, type-sensitive structural equality (DataWeave's own == already does this correctly for
// the order-sensitive case) — the recursive part below only exists to apply ignoreArrayOrder at
// every nesting level, sorting arrays by their canonical JSON text before comparing element-wise.
fun jsonEquals(a, b, ignoreArr: Boolean): Boolean =
    if (!ignoreArr) (a == b)
    else if (a is Array and b is Array)
        (sizeOf(a) == sizeOf(b) and do {
            var sa = a orderBy ((x) -> write(x, "application/json"))
            var sb = b orderBy ((x) -> write(x, "application/json"))
            ---
            sizeOf(sa) == 0 or (0 to (sizeOf(sa) - 1)) every ((i) -> jsonEquals(sa[i], sb[i], ignoreArr))
        })
    else if (a is Object and b is Object)
        (sizeOf(a) == sizeOf(b) and (namesOf(a) every ((k) -> jsonEquals(a[k], b[k], ignoreArr))))
    else (a == b)

// "partial": every key in EXPECTED (right) must exist and deep-match in ACTUAL (left); extra
// keys in left are ignored. If right isn't an object, there's no such thing as "subset of a
// scalar/array" — degrades to full jsonEquals, matching the reference.
fun isSubset(left, right, ignoreArr: Boolean): Boolean =
    if (!(right is Object)) jsonEquals(left, right, ignoreArr)
    else if (!(left is Object)) false
    else (namesOf(right) every ((k) -> jsonEquals(left[k], right[k], ignoreArr)))

// "keys-only": compares field-NAME sets only (values never inspected) — recurses through
// arrays index-by-index (since arrays have no names of their own), but not into an object
// field's value even if that value is itself an object.
fun sameTopLevelKeys(left, right): Boolean =
    if (left is Array and right is Array)
        (sizeOf(left) == sizeOf(right) and
            (sizeOf(left) == 0 or (0 to (sizeOf(left) - 1)) every ((i) -> sameTopLevelKeys(left[i], right[i]))))
    else if (!(left is Object) or !(right is Object)) (left == right)
    else ((namesOf(left) orderBy ((k) -> k)) == (namesOf(right) orderBy ((k) -> k)))

var step = payload
var stepType = step.'type' default "jsoncompare"
var bodyVal = vars.postChainBody
var varsFloor = vars.rsVars default {}

// "expression" isn't wired up in the reference implementation either — it falls through to the
// same default (body) branch there, so it does here too.
fun resolveJsonSide(source, exprName, literal) =
    if (source == "variable") asJson(varsFloor[(trim(exprName default ""))])
    else if (source == "literal") (try(() -> read(literal default "", "application/json")) orElse null)
    else asJson(bodyVal)

fun resolveTextSide(source, exprName, literal) =
    if (source == "variable") stringifyVal(varsFloor[(trim(exprName default ""))])
    else if (source == "literal") (literal default "")
    else stringifyVal(bodyVal)

var stepName = if (step.name != null and trim(step.name) != "") step.name else (stepType ++ " compare")
var stepOnMismatch = step.onMismatch default "stop"
var stepResultVar = trim(step.resultVar default "")

var evalResult =
    if (stepType == "textcompare")
        do {
            var left = resolveTextSide(step.leftSource default "body", step.leftExpr, step.leftLiteral)
            var right = resolveTextSide(step.rightSource default "literal", step.rightExpr, step.rightLiteral)
            var cs = step.caseSensitive default true
            var mode = step.mode default "exact"
            var l = if (cs) left else lower(left)
            var r = if (cs) right else lower(right)
            var passed =
                if (mode == "contains") (l contains r)
                else if (mode == "starts-with") startsWith(l, r)
                else if (mode == "ends-with") endsWith(l, r)
                else if (mode == "regex") (sizeOf(scan(left, (if (cs) right else ("(?i)" ++ right)))) > 0)
                else (l == r)
            ---
            { passed: passed, mode: mode, actualText: ("\"" ++ left ++ "\""), expectedText: ("\"" ++ right ++ "\"") }
        }
    else
        do {
            var left = resolveJsonSide(step.leftSource default "body", step.leftExpr, step.leftLiteral)
            var right = resolveJsonSide(step.rightSource default "literal", step.rightExpr, step.rightLiteral)
            var ignoreArr = step.ignoreArrayOrder default false
            var mode = step.mode default "deep-equal"
            var passed =
                if (mode == "partial") isSubset(left, right, ignoreArr)
                else if (mode == "keys-only") sameTopLevelKeys(left, right)
                else jsonEquals(left, right, ignoreArr)
            ---
            { passed: passed, mode: mode, actualText: write(left default null, "application/json"), expectedText: write(right default null, "application/json") }
        }

var checkResult = { name: stepName, "type": stepType, passed: evalResult.passed }
    ++ (if (evalResult.passed) {} else {
        message: (stepType ++ " mismatch (mode=" ++ evalResult.mode ++ ")\n  actual:   " ++ evalResult.actualText ++ "\n  expected: " ++ evalResult.expectedText)
    })
---
{ check: checkResult, passed: evalResult.passed, onMismatch: stepOnMismatch, resultVar: stepResultVar }
